// Icone rend une icône. Elle ne contient PLUS le tracé : celui-ci vit dans la
// feuille de style partagée, en masque CSS, et la balise n'est qu'une classe.
//
// Pourquoi. Le tracé de « landmark » fait un kilo-octet ; neuf icônes de
// navigation et cinq de barre basse en font douze, sur CHACUNE des 40 000 pages
// du site — quatre cent quatre-vingts méga-octets de tracés identiques répétés.
// Le masque CSS met la même chose dans un fichier téléchargé une fois. La
// balise reste décorative (aria-hidden), et chaque icône garde son libellé
// écrit à côté : une icône ne porte jamais seule une information.
func Icone(cle string) template.HTML {
	if _, ok := icones[cle]; !ok {
		return ""
	}
	return template.HTML(`<i class="ico i-` + cle + `" aria-hidden="true"></i>`)
}

// IconesCSS produit les règles de masque, une par icône. Le SVG est inséré en
// data URI : seuls les caractères que la syntaxe url() ne supporte pas sont
// échappés, ce qui reste bien plus court qu'un encodage en base64.
func IconesCSS() string {
	var b strings.Builder
	b.WriteString("\n/* ── Icônes Font Awesome Free 6.7.2, en masques CSS ───────────────────\n" +
		"   Tracés officiels, sous CC BY 4.0, attribués au pied de chaque page.\n" +
		"   Servis ici et non dans le HTML : le même tracé sur 40 000 pages\n" +
		"   pesait des centaines de méga-octets. Aucun appel vers un tiers. */\n")
	b.WriteString(".ico{display:inline-block;width:1em;height:1em;flex:0 0 auto;" +
		"background-color:currentColor;" +
		"-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;" +
		"-webkit-mask-position:center;mask-position:center;" +
		"-webkit-mask-size:contain;mask-size:contain}\n")
	cles := make([]string, 0, len(icones))
	for c := range icones {
		cles = append(cles, c)
	}
	sort.Strings(cles)
	for _, c := range cles {
		i := icones[c]
		u := "data:image/svg+xml," + echapperURL(
			`<svg xmlns="http://www.w3.org/2000/svg" viewBox="`+i.vb+
				`"><path d="`+i.d+`"/></svg>`)
		fmt.Fprintf(&b, ".i-%s{-webkit-mask-image:url(\"%s\");mask-image:url(\"%s\")}\n", c, u, u)
	}
	return b.String()
}

// echapperURL : dans une url("…") de feuille de style, seuls le guillemet
// double, le dièse, le chevron et le pourcent doivent partir. Tout le reste
// passe tel quel, y compris les espaces et les virgules du tracé.
func echapperURL(s string) string {
	return strings.NewReplacer(
		"%", "%25", "\"", "%22", "#", "%23", "<", "%3C", ">", "%3E",
		"{", "%7B", "}", "%7D", "|", "%7C", "\\", "%5C", "^", "%5E",
		"\n", "", "\r", "",
	).Replace(s)
}
